// stlport
// BFME 2 has no AnimationSteeringUpdate module: retail game.dat carries no
// "AnimationSteering" string (ASCII or UTF-16) while other module names such
// as "SlavedUpdate" are there, the module-data ctor once rowed under that name
// is another module's (AnimationSteeringUpdateModuleDataCtor.cpp), and the
// ledger holds no row for any AnimationSteeringUpdate method. The Zero Hour
// bodies this port carried were nonmatching reconstructions of code retail
// never had; their references (DISABLEDMASK_NONE, Drawable model-condition
// setters, UpdateModule::crc, non-retail ModuleData dtors) kept the unit from
// linking. Only _Base_bitset<4>::_M_do_reset (0x00388815) is a retail body
// here; the explicit instantiation below emits it.
#define Matrix4x4 Matrix4  // BFME renamed it
#define __PLACEMENT_VEC_NEW_INLINE  // always.h/GameMemory.h define array placement-new themselves
#include "PreRTS.h"	// This must go first in EVERY cpp file int the GameEngine
#include <bitset>

namespace _STL { template void _Base_bitset<4>::_M_do_reset(); }
